// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract LowQuorum {uint public supply=1_000_000;function passed(uint votes) external pure returns(bool){return votes>=1;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SnapshotQuorum {uint public snapshotSupply=1_000_000;function passed(uint votes) external view returns(bool){return votes*100>=snapshotSupply*10;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract PublicReveal {bytes32 public answer;function submit(bytes32 guess) external view returns(bool){return guess==answer;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract CommitReveal {mapping(address=>bytes32) public commit;function commitHash(bytes32 h) external {commit[msg.sender]=h;}function reveal(bytes32 value,bytes32 salt) external view returns(bool){return keccak256(abi.encode(value,salt))==commit[msg.sender];} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract BlockhashRandom {function draw() external view returns(uint){return uint(blockhash(block.number-1))%100;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IVRF{function request() external returns(uint);} contract VrfConsumer {IVRF public vrf;constructor(IVRF v){vrf=v;}function draw() external returns(uint){return vrf.request();}}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract CrossChainReplay {mapping(bytes32=>bool) public executed;function execute(bytes calldata message,bytes calldata sig) external {bytes32 id=keccak256(message);require(!executed[id]);executed[id]=true;sig;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract CrossChainDomain {mapping(bytes32=>bool) public executed;address public messenger;constructor(address m){messenger=m;}function execute(uint sourceChain,bytes calldata message) external {require(msg.sender==messenger);bytes32 id=keccak256(abi.encode(sourceChain,block.chainid,address(this),message));require(!executed[id]);executed[id]=true;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MinimalVault {mapping(address=>uint) public balance;function deposit() external payable {balance[msg.sender]+=msg.value;}function withdraw(uint a) external {require(balance[msg.sender]>=a);balance[msg.sender]-=a;(bool ok,)=msg.sender.call{value:a}("");require(ok);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IExternalRisk {function score(address) external view returns(uint);} contract ExternalDependency {IExternalRisk public source;constructor(IExternalRisk s){source=s;}function allowed(address a) external view returns(bool){return source.score(a)<50;} }
